"""Apply the contribution-contract v2 to IND records after build_records.py."""
import json
from pathlib import Path
P=Path(__file__).parent

def get(name): return json.loads((P/name).read_text())
def save(name,x): (P/name).write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
cases=get('cases.json'); claims=get('claims.json'); sources=get('sources.json'); graph=get('graph.json')

